@startuml

class Bus {
  + licensePlate : string
  + inRepairShop : boolean
}

class Driver {
  + id : int
  + name : string
  + onSickLeave : boolean
}

class Route {
  + routeNumber : int
}

class Shift {
  + shiftType : string
}

class Assignment {
  + date : date
}

Bus "1" -- "*" Assignment
Driver "1" -- "*" Assignment
Route "1" -- "*" Assignment
Assignment "0..1" -- "1" Bus
Assignment "0..1" -- "1" Driver

@enduml

